using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1Refine {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B1/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_FullFloor/";
 static GameObject Child(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static Material Mat(string n)=>AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/B1M_"+n+".mat");
 static GameObject Box(string n,Transform p,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=m;return g;}
 public static object Run(){var scene=SceneManager.GetActiveScene();if(Application.isPlaying||scene.isDirty||!scene.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 only");var root=scene.GetRootGameObjects().Single(g=>g.name=="B1_ResearchAndStaffFloor").transform;var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
  foreach(var text in root.GetComponentsInChildren<TextMesh>(true))UnityEngine.Object.DestroyImmediate(text.gameObject);
  foreach(var r in plan["rooms"]){string id=(string)r["id"];float radius=(float)r["r"];var room=root.Find("B1_"+id+"_Sector");var arch=room.Find("Architecture");var eq=room.Find("Equipment");var mat=new Material(Shader.Find("Universal Render Pipeline/Unlit")){name="BL_Sign_"+id};mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/BL_Sign_"+id+".png"));AssetDatabase.CreateAsset(mat,E+"Materials/"+mat.name+".mat");
   foreach(var d in r["doors"]){var dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;var g=GameObject.CreatePrimitive(PrimitiveType.Quad);g.name="B1_"+id+"_MountedSign_"+(string)d["id"];g.transform.SetParent(arch,false);g.transform.localPosition=dir*(radius-1.35f)+Vector3.up*3.12f;g.transform.localRotation=Quaternion.LookRotation(dir);g.transform.localScale=new Vector3(1.52f,.38f,1);UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=mat;
    var backing=Box("SignHousing_"+(string)d["id"],arch,g.transform.localPosition+dir*.035f,new Vector3(1.58f,.43f,.06f),Mat("Dark"));backing.transform.localRotation=g.transform.localRotation;
    foreach(float side in new[]{-.55f,.55f}){var sidevec=Quaternion.LookRotation(dir)*Vector3.right*side;var start=g.transform.localPosition+sidevec+Vector3.up*.23f;Box("SignSuspension",arch,start+Vector3.up*.25f,new Vector3(.018f,.50f,.018f),Mat("Steel"));}
   }
   foreach(var g in eq.Cast<Transform>().Where(t=>t.name.Contains("TaskChair")||t.name.Contains("PairedChair")).ToArray())UnityEngine.Object.DestroyImmediate(g.gameObject);
   foreach(var p in plan["placements"].Where(q=>(string)q["room"]==id&&(string)q["role"]=="Seating")){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((string)p["asset"]),eq);g.name=(string)p["name"];g.transform.localPosition=new Vector3((float)p["position"][0],0,(float)p["position"][2]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);var c=g.AddComponent<BoxCollider>();c.size=new Vector3((float)p["size"][0],(float)p["size"][1],(float)p["size"][2]);c.center=new Vector3((float)p["center"][0],(float)p["center"][1],(float)p["center"][2]);}
  }
  foreach(var l in root.GetComponentsInChildren<Light>(true)){string n=l.transform.parent.name;if(n.Contains("DoorLight")){l.enabled=false;continue;}if(n.Contains("CeilingLight"))l.intensity*=4.2f;else if(n.Contains("CoreLight"))l.intensity*=2.2f;else l.intensity*=1.7f;}
  foreach(var rr in root.GetComponentsInChildren<MeshRenderer>()){if(!rr.transform.parent||!rr.transform.parent.name.Contains("Light"))continue;rr.sharedMaterials=rr.sharedMaterials.Select(m=>m&&m.name.IndexOf("Lamp",StringComparison.OrdinalIgnoreCase)>=0?Mat("Lamp"):m).ToArray();}
  RenderSettings.ambientSkyColor=new Color(.31f,.31f,.30f);RenderSettings.ambientEquatorColor=new Color(.25f,.25f,.24f);RenderSettings.ambientGroundColor=new Color(.15f,.15f,.14f);
  // R1 remains the existing white double-solid staff route convention.
  var guide=Child("B1_R1_StaffWayfinding",root).transform;var line=new Material(Mat("Mark")){name="BL_R1_StaffLine"};line.color=new Color(.76f,.80f,.78f);AssetDatabase.CreateAsset(line,E+"Materials/BL_R1_StaffLine.mat");
  foreach(var t in plan["tunnels"]){var pts=t["path"].Select(p=>new Vector3((float)p[0],.010f,-(float)p[1])).ToArray();for(int i=1;i<pts.Length;i++){var a=pts[i-1];var b=pts[i];var dir=(b-a).normalized;var right=Vector3.Cross(Vector3.up,dir);float len=Vector3.Distance(a,b);foreach(float sign in new[]{-1f,1f}){var g=Box("R1_"+(string)t["id"]+"_"+i+"_"+sign,guide,(a+b)*.5f+right*(sign*.09f),new Vector3(.035f,.003f,Mathf.Max(.01f,len-.006f)),line);g.transform.localRotation=Quaternion.LookRotation(dir);}}}
  foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(scene);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);return new{lights=root.GetComponentsInChildren<Light>().Count(l=>l.enabled),signs=44,pairedChairs=plan["placements"].Count(p=>(string)p["role"]=="Seating")};
 }
}
